From 78c09562ccb96f5ce95a87cabc2514ac9363c20b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:16:20 +0100
Subject: [PATCH] layershell: keep the panel under the pointer above activated
 fullscreen

When a fullscreen window became active while the pointer was on a panel,
for example after closing Kickoff, it covered the panel at once and hid
an auto-hide one; now the panel stays above until the pointer leaves it.

BUG: 519796
---
 src/layershellv1window.cpp | 52 +++++++++++++++++++++++++++++++++++++-
 src/layershellv1window.h   |  4 +++
 2 files changed, 55 insertions(+), 1 deletion(-)

diff --git a/src/layershellv1window.cpp b/src/layershellv1window.cpp
index bee106ff1b..40f3660cee 100644
--- a/src/layershellv1window.cpp
+++ b/src/layershellv1window.cpp
@@ -7,6 +7,7 @@
 #include "layershellv1window.h"
 #include "core/output.h"
 #include "core/pixelgrid.h"
+#include "cursor.h"
 #include "layershellv1integration.h"
 #include "screenedge.h"
 #include "wayland/layershell_v1.h"
@@ -57,6 +58,8 @@ LayerShellV1Window::LayerShellV1Window(LayerSurfaceV1Interface *shellSurface,

     connect(workspace(), &Workspace::outputRemoved,
             this, &LayerShellV1Window::handleOutputRemoved);
+    connect(workspace(), &Workspace::windowActivated,
+            this, &LayerShellV1Window::handleWindowActivated);

     connect(shellSurface->surface(), &SurfaceInterface::sizeChanged,
             this, &LayerShellV1Window::handleSizeChanged);
@@ -221,7 +224,7 @@ Layer LayerShellV1Window::belongsToLayer() const
     case LayerSurfaceV1Interface::BottomLayer:
         return BelowLayer;
     case LayerSurfaceV1Interface::TopLayer:
-        return AboveLayer;
+        return m_keepAboveActiveFullScreen ? ActiveLayer : AboveLayer;
     case LayerSurfaceV1Interface::OverlayLayer:
         return OverlayLayer;
     default:
@@ -391,6 +394,53 @@ void LayerShellV1Window::deactivateScreenEdge()
     unreserveScreenEdge();
 }

+void LayerShellV1Window::handleWindowActivated(Window *window)
+{
+    setKeepAboveActiveFullScreen(false);
+
+    if (!window || !window->isFullScreen() || !isDock() || isHidden() || !window->isOnOutput(output())
+        || !frameGeometry().contains(Cursors::self()->mouse()->pos())) {
+        return;
+    }
+
+    // A panel under the pointer stays above a fullscreen window that becomes active until the pointer leaves it,
+    // unless a fullscreen window already covered it. The stacking order isn't updated yet at this point.
+    const QList<Window *> &stack = workspace()->stackingOrder();
+    for (qsizetype i = stack.indexOf(this) + 1; i < stack.size(); ++i) {
+        if (stack[i]->isFullScreen() && stack[i]->isOnOutput(output())) {
+            return;
+        }
+    }
+    setKeepAboveActiveFullScreen(true);
+}
+
+void LayerShellV1Window::handleCursorMoved(const QPointF &pos)
+{
+    if (isHidden() || !frameGeometry().contains(pos)) {
+        setKeepAboveActiveFullScreen(false);
+    }
+}
+
+void LayerShellV1Window::setKeepAboveActiveFullScreen(bool keep)
+{
+    if (m_keepAboveActiveFullScreen == keep) {
+        return;
+    }
+    m_keepAboveActiveFullScreen = keep;
+
+    if (keep) {
+        connect(Cursors::self()->mouse(), &Cursor::posChanged, this, &LayerShellV1Window::handleCursorMoved);
+    } else {
+        disconnect(Cursors::self()->mouse(), &Cursor::posChanged, this, &LayerShellV1Window::handleCursorMoved);
+    }
+
+    StackingUpdatesBlocker blocker(workspace());
+    updateLayer();
+    if (keep) {
+        workspace()->raiseWindow(this);
+    }
+}
+
 void LayerShellV1Window::handleTargetScaleChange()
 {
     moveResize(snapToPixels(m_moveResizeGeometry, m_targetScale));
diff --git a/src/layershellv1window.h b/src/layershellv1window.h
index 9f7a6e1d64..2ccd950578 100644
--- a/src/layershellv1window.h
+++ b/src/layershellv1window.h
@@ -70,12 +70,16 @@ private:
     void reserveScreenEdge();
     void unreserveScreenEdge();
     void handleTargetScaleChange();
+    void handleWindowActivated(Window *window);
+    void handleCursorMoved(const QPointF &pos);
+    void setKeepAboveActiveFullScreen(bool keep);

     LogicalOutput *m_desiredOutput;
     LayerShellV1Integration *m_integration;
     LayerSurfaceV1Interface *m_shellSurface;
     QPointer<AutoHideScreenEdgeV1Interface> m_screenEdge;
     bool m_screenEdgeActive = false;
+    bool m_keepAboveActiveFullScreen = false;
     WindowType m_windowType;
     QList<LayerShellV1ConfigureEvent> m_configureEvents;
     QTimer m_rescalingTimer;
